export type Section = 'inicio' | 'unidades' | 'rentas' | 'servicios' | 'pagos' | 'finanzas' | 'financiamientos' | 'socios' | 'aportaciones' | 'proyecciones' | 'accesos' | 'reportes';
export type UnitStatus = 'Activa' | 'Pendiente' | 'Inactiva';
export type Unit = { id: string; code: string; name: string; area: string; status: UnitStatus; rent: number; nextDue: string; createdAt: string };
type Service = { id: string; name: string; type: 'Fijo' | 'Variable'; amount: number };
type Rent = { id: string; period: string; unitId: string; type: 'Fija' | 'Variable'; due: string; amount: number; status: 'Pagada' | 'Vencida' | 'Pendiente' };
type Payment = { id: string; period: string; unitId: string; date: string; responsible: string; method: string; amount: number };
type Movement = { id: string; period: string; unitId: string; date: string; type: 'Venta' | 'Gasto'; concept: string; amount: number };
type Financing = { id: string; unitId: string; concept: string; amount: number; paid: number };
type Partner = { id: string; name: string; unitId: string; share: number };
type Contribution = { id: string; period: string; partnerId: string; concept: string; method: string; notes: string; amount: number };
type AccessUser = { id: string; name: string; email: string; role: 'Administrador' | 'Socio · solo lectura'; unitId: string };

export type FinanceMocks = {
  units: Unit[]; services: Service[]; rents: Rent[]; payments: Payment[];
  movements: Movement[]; financings: Financing[]; partners: Partner[];
  contributions: Contribution[]; accessUsers: AccessUser[]; history: number[];
};

