  const [editing, setEditing] = useState<Service | null | 'new'>(null); const save = (values: Record<string, string>) => { const current = editing === 'new' ? null : editing; const record: Service = { id: current?.id ?? uid(), name: text(values, 'name'), type: values.type as Service['type'], amount: number(values, 'amount') }; setMocks((data) => ({ ...data, services: current ? data.services.map((row) => row.id === current.id ? record : row) : [...data.services, record] })); };
