function ProjectionsPage({ mocks }: { mocks: FinanceMocks }) {
  const average = mocks.history.reduce((sum, value) => sum + value, 0) / Math.max(mocks.history.length, 1); const recent = mocks.history.slice(-3); const trend = ((mocks.history.at(-1) ?? 0) - (mocks.history.at(-2) ?? 0)) / Math.max(mocks.history.at(-2) ?? 1, 1); const next = recent.reduce((sum, value) => sum + value, 0) / Math.max(recent.length, 1) * (1 + trend);
  return <><SectionHeader eyebrow="ANÁLISIS PREDICTIVO" title="Proyección de ventas" description="Pronóstico automático actualizado con los datos históricos."><Button variant="outline" onClick={() => downloadCsv('proyeccion-ventas.csv', mocks.history.map((value, index) => ({ mes: index + 1, ventas: value })))}><Download /> Excel/CSV</Button></SectionHeader><div className="metric-grid three"><Metric icon={<BarChart3 />} label="Promedio mensual consolidado" value={money(average)} detail={`${mocks.history.length} meses analizados`} /><Metric icon={<TrendingUp />} label="Tendencia del último mes" value={`${(trend * 100).toFixed(1)}%`} detail="Crecimiento o estabilidad" tone={trend >= 0 ? 'positive' : 'negative'} /><Metric icon={<ArrowUpRight />} label="Proyección próximo mes" value={money(next)} detail="Promedio y tendencia reciente" /></div><Card><CardHeader><CardTitle>Ventas consolidadas · últimos 12 meses</CardTitle><CardDescription>La barra punteada representa la proyección.</CardDescription></CardHeader><CardContent><BarChart values={mocks.history} projected={next} /></CardContent></Card><Card><CardHeader><CardTitle>Proyección por sucursal</CardTitle><CardDescription>Pronóstico distribuido uniformemente como base editable.</CardDescription></CardHeader><CardContent className="projection-grid">{mocks.units.map((unit) => <article key={unit.id}><strong>{unit.code}</strong><span>{unit.name}</span><div><small>Próximo mes</small><b>{money(next / Math.max(mocks.units.length, 1))}</b></div><div><small>Proyección 3 meses</small><b>{money(next * 3 / Math.max(mocks.units.length, 1))}</b></div></article>)}</CardContent></Card></>;
}

function AccessPage({ mocks, setMocks }: { mocks: FinanceMocks; setMocks: MocksSetter }) {
  const [editing, setEditing] = useState<AccessUser | null | 'new'>(null); const save = (values: Record<string, string>) => { const current = editing === 'new' ? null : editing; const record: AccessUser = { id: current?.id ?? uid(), name: text(values, 'name'), email: text(values, 'email'), role: values.role as AccessUser['role'], unitId: values.unitId }; setMocks((data) => ({ ...data, accessUsers: current ? data.accessUsers.map((row) => row.id === current.id ? record : row) : [...data.accessUsers, record] })); };
  return <><SectionHeader eyebrow="CONTROL MASTER DE ACCESOS" title="Usuarios y accesos" description="Autoriza administradores o crea socios de solo lectura para una, varias o todas las sucursales."><Button onClick={() => setEditing('new')}><UserPlus /> Autorizar usuario</Button></SectionHeader><div className="notice-success"><ShieldCheck /><div><strong>El usuario Master conserva el control general</strong><p>Esta versión simula perfiles. Los cambios desaparecen al recargar la página.</p></div></div><Card><CardHeader><CardTitle>Perfiles autorizados</CardTitle></CardHeader><CardContent className="record-list">{mocks.accessUsers.map((user) => <div className="record-row" key={user.id}><div className="user-list-avatar">{user.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</div><div><strong>{user.name}</strong><small>{user.email} · {user.unitId === 'all' ? 'Todas las sucursales' : unitById(mocks, user.unitId)?.code}</small></div><Status value={user.role} /><RowActions label={user.name} onEdit={() => setEditing(user)} onDelete={() => setMocks((data) => ({ ...data, accessUsers: data.accessUsers.filter((row) => row.id !== user.id) }))} /></div>)}</CardContent></Card><RecordDialog open={editing !== null} onOpenChange={(open) => !open && setEditing(null)} title={editing === 'new' ? 'Autorizar usuario' : 'Editar acceso'} fields={[{ label: 'Nombre', name: 'name' }, { label: 'Correo', name: 'email', type: 'email' }, { label: 'Rol', name: 'role', options: ['Administrador', 'Socio · solo lectura'].map((value) => ({ label: value, value })) }, { label: 'Sucursal', name: 'unitId', options: [{ label: 'Todas', value: 'all' }, ...unitOptions(mocks)] }]} initial={editing && editing !== 'new' ? editing : { role: 'Administrador', unitId: 'all' }} onSubmit={save} submitLabel="Guardar acceso" /></>;
}

function ReportsPage({ mocks, period }: { mocks: FinanceMocks; period: string }) {
  const reports = [{ key: 'summary', icon: <BarChart3 />, title: 'Resumen ejecutivo', description: 'Ingresos, rentas, pagos y servicios' }, { key: 'company', icon: <Building2 />, title: 'Empresa consolidada', description: 'Reporte general de todas las sucursales' }, { key: 'units', icon: <Building2 />, title: 'Directorio de sucursales', description: 'Altas, áreas y estado actual' }, { key: 'rents', icon: <ReceiptText />, title: 'Rentas del mes', description: 'Rentas fijas y variables, vencimientos y estado' }, { key: 'financials', icon: <CircleDollarSign />, title: 'Estado financiero', description: 'Ventas, gastos y utilidad neta' }, { key: 'partners', icon: <Users />, title: 'Utilidad por socio', description: 'Participación por sucursal' }, { key: 'contributions', icon: <WalletCards />, title: 'Aportaciones de socios', description: 'Aportaciones manuales descontadas' }, { key: 'history', icon: <TrendingUp />, title: 'Proyección de ventas', description: 'Promedios, tendencias y pronóstico' }];
  const rowsFor = (key: string): Record<string, string | number>[] => key === 'units' || key === 'company' ? mocks.units : key === 'rents' ? mocks.rents.filter((row) => row.period === period) : key === 'financials' ? mocks.movements.filter((row) => row.period === period) : key === 'partners' ? mocks.partners : key === 'contributions' ? mocks.contributions.filter((row) => row.period === period) : key === 'history' ? mocks.history.map((value, index) => ({ mes: index + 1, ventas: value })) : [{ periodo: period, sucursales: mocks.units.length, rentas: mocks.rents.length, pagos: mocks.payments.length }];
  return <><SectionHeader title="Reportes descargables" description={`Formatos de ${monthLabel(period)} listos para impresión y archivos compatibles con Excel.`}><Button onClick={() => window.print()}><FileBarChart /> Reporte general</Button></SectionHeader><Card><CardHeader><CardTitle>Formato de visualización</CardTitle><CardDescription>El estilo formal corporativo se aplica a la impresión.</CardDescription></CardHeader><CardContent className="template-grid"><article className="selected"><Landmark /><strong>Formal corporativo</strong><span>Logotipo, encabezado institucional e indicadores</span><Badge>Predeterminado</Badge></article><article><ReceiptText /><strong>Contable</strong><span>Líneas y estructura de libro</span></article><article><CircleDollarSign /><strong>Financiero</strong><span>Énfasis en resultados y rentabilidad</span></article></CardContent></Card><div className="reports-grid">{reports.map((report) => <Card key={report.key}><CardContent className="report-card"><div className="catalog-icon">{report.icon}</div><div><strong>{report.title}</strong><p>{report.description}</p></div><Button variant="outline" size="sm" onClick={() => window.print()}>Previsualizar</Button><Button size="sm" onClick={() => downloadCsv(`${report.key}-${period}.csv`, rowsFor(report.key))}><Download /> Excel</Button></CardContent></Card>)}</div></>;
}
